import type { ReactNode } from 'react'
import { CodeBlock } from '../components/terminal'

/**
 * Light Markdown renderer for the evidence README generated by evidence/bundle.py::render_report.
 * It covers only what the generator emits: ATX headings, paragraphs (with hard line breaks), a block of
 * `**Key:** value` lines (rendered as a fact list), unordered lists, fenced code, pipe tables,
 * blockquotes, horizontal rules, and inline `code`, **bold** and links. Everything is emitted as React
 * elements; no HTML from the document is ever injected, and no text is rewritten.
 */
export function renderMarkdown(src: string): ReactNode[] {
  const lines = src.replace(/\r\n/g, '\n').split('\n')
  const out: ReactNode[] = []
  let i = 0
  let key = 0
  const k = () => `md-${key++}`
  while (i < lines.length) {
    const line = lines[i]
    if (!line.trim()) {
      i++
      continue
    }
    if (line.startsWith('```')) {
      const buf: string[] = []
      i++
      while (i < lines.length && !lines[i].startsWith('```')) buf.push(lines[i++])
      i++
      out.push(<CodeBlock key={k()} text={buf.join('\n')} />)
      continue
    }
    const h = /^(#{1,6})\s+(.*)$/.exec(line)
    if (h) {
      const level = Math.min(3, h[1].length)
      const text = inline(h[2])
      out.push(level === 1 ? <h1 key={k()}>{text}</h1> : level === 2 ? <h2 key={k()}>{text}</h2> : <h3 key={k()}>{text}</h3>)
      i++
      continue
    }
    if (/^(-{3,}|\*{3,})$/.test(line.trim())) {
      out.push(<hr key={k()} />)
      i++
      continue
    }
    if (line.startsWith('|')) {
      const rows: string[] = []
      while (i < lines.length && lines[i].startsWith('|')) rows.push(lines[i++])
      const cells = (r: string) =>
        r
          .trim()
          .replace(/^\||\|$/g, '')
          .split('|')
          .map((c) => c.trim())
      const head = cells(rows[0])
      const body = rows.slice(1).filter((r) => !/^\|[\s:|-]+\|$/.test(r.trim()))
      out.push(
        <div key={k()} className="md-table">
          <table>
            <thead>
              <tr>
                {head.map((c, j) => (
                  <th key={j}>{inline(c)}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {body.map((r, j) => (
                <tr key={j}>
                  {cells(r).map((c, jj) => (
                    <td key={jj} data-label={head[jj] ?? ''}>
                      {inline(c)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>,
      )
      continue
    }
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = []
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) items.push(lines[i++].replace(/^\s*[-*]\s+/, ''))
      out.push(
        <ul key={k()}>
          {items.map((t, j) => (
            <li key={j}>{inline(t)}</li>
          ))}
        </ul>,
      )
      continue
    }
    if (line.startsWith('>')) {
      const buf: string[] = []
      while (i < lines.length && lines[i].startsWith('>')) buf.push(lines[i++].replace(/^>\s?/, ''))
      out.push(<blockquote key={k()}>{inline(buf.join(' '))}</blockquote>)
      continue
    }
    const buf: string[] = []
    while (i < lines.length && lines[i].trim() && !/^(#{1,6}\s|```|\||\s*[-*]\s|>)/.test(lines[i])) buf.push(lines[i++])
    // a run of "**Key:** value" lines is a fact list (the report header)
    const facts = buf.map((l) => /^\*\*([^*]+?):\*\*\s*(.*?)\s*$/.exec(l))
    if (buf.length > 1 && facts.every(Boolean)) {
      out.push(
        <dl key={k()} className="md-facts">
          {facts.map((m, j) => (
            <div key={j}>
              <dt>{m![1]}</dt>
              <dd>{inline(m![2])}</dd>
            </div>
          ))}
        </dl>,
      )
      continue
    }
    // two trailing spaces are a hard line break; otherwise lines join with a space
    const parts: ReactNode[] = []
    buf.forEach((l, j) => {
      parts.push(...inline(l.replace(/\s+$/, '')))
      if (j < buf.length - 1) parts.push(/ {2,}$/.test(l) ? <br key={`br${j}`} /> : ' ')
    })
    out.push(<p key={k()}>{parts}</p>)
  }
  return out
}

/** Inline code, bold and links; everything else is literal text. */
function inline(text: string): ReactNode[] {
  const parts: ReactNode[] = []
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[([^\]]+)\]\(([^)\s]+)\))/g
  let last = 0
  let m: RegExpExecArray | null
  let n = 0
  while ((m = re.exec(text))) {
    if (m.index > last) parts.push(text.slice(last, m.index))
    if (m[1]) parts.push(<code key={n++}>{m[1].slice(1, -1)}</code>)
    else if (m[2]) parts.push(<strong key={n++}>{m[2].slice(2, -2)}</strong>)
    else if (m[3]) {
      const href = m[5]
      const safe = /^(https?:|\/|#|\.)/.test(href)
      parts.push(
        safe ? (
          <a key={n++} href={href} target="_blank" rel="noreferrer">
            {m[4]}
          </a>
        ) : (
          <span key={n++}>{m[4]}</span>
        ),
      )
    }
    last = m.index + m[0].length
  }
  if (last < text.length) parts.push(text.slice(last))
  return parts
}
